#!/usr/bin/env node
/**
 * Put the published corpus into the app, as text, with the ledger's digest beside it.
 *
 * ```
 * content/versions/<label>.json   the immutable bundle
 * content/versions/index.json     the ledger row that vouches for it
 *          ↓
 * apps/mobile/src/corpus/generated/bundle.ts   ← committed, --check in gate 11
 * ```
 *
 * ## Why the text and the digest are two separate exports
 *
 * A bundle carrying its own expected checksum verifies itself. The expected value lives in the
 * **ledger** for that reason ([ADR-0046](../docs/adr/0046-published-corpus-is-an-immutable-generated-bundle.md)),
 * and this script keeps them apart on the way in: `BUNDLE_TEXT` is the file, `ROOT_DIGEST` is
 * the ledger's row. `loadPublishedVersion` is then given two things that came from two places,
 * which is the only arrangement in which the comparison means anything.
 *
 * ## Why text rather than an import
 *
 * `content/` sits outside `apps/mobile/`, so Metro cannot see it without a watch folder — and
 * `loadPublishedVersion` takes text, not an object. Importing the JSON and re-serialising it
 * would verify correctly (the digest is over a canonical form, not over file bytes) at the cost
 * of rebuilding a 450 KB string on every cold start, and it would put one more transformation
 * between the published file and the checked artefact (ADR-0066).
 *
 * ```
 * node scripts/generate-corpus-bundle.mjs           regenerate
 * node scripts/generate-corpus-bundle.mjs --check   verify it is current, write nothing
 * ```
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { loadCorpusPackage, ROOT, sha256 } from './corpus-io.mjs';

const GREEN = '\x1b[32m',
  RED = '\x1b[31m',
  DIM = '\x1b[2m',
  BOLD = '\x1b[1m',
  OFF = '\x1b[0m';

const CHECK = process.argv.includes('--check');
const VERSIONS = join(ROOT, 'content', 'versions');
const OUT_DIR = join(ROOT, 'apps', 'mobile', 'src', 'corpus', 'generated');
const OUT = join(OUT_DIR, 'bundle.ts');

console.log(`${BOLD}Corpus bundle → app${OFF}\n`);

const { assertSha256, parseLedger, loadPublishedVersion } = await loadCorpusPackage();

// The generator hashes, so the primitive it hashes with is checked first. Same order as the
// publish path: a checksum is a tamper control and cannot rest on an unverified hasher.
assertSha256(sha256);

const ledgerPath = join(VERSIONS, 'index.json');
if (!existsSync(ledgerPath)) {
  console.log(`  ${RED}x${OFF} no ledger at ${ledgerPath}`);
  process.exit(1);
}

const ledger = parseLedger(JSON.parse(readFileSync(ledgerPath, 'utf8')), 'index.json');
if (ledger.length === 0) {
  console.log(
    `  ${RED}x${OFF} the ledger is empty. There is no published version for the app to pin, ` +
      'and an app with no corpus has nothing to browse.',
  );
  process.exit(1);
}

/**
 * The pinned version is the LAST ledger row.
 *
 * The ledger is append-only, so the last row is the newest publish. Pinning by "newest at
 * generation time" rather than by a constant repeated here means the label cannot drift out of
 * step with what was actually published — and because the result is a committed file, which
 * version the app holds is still a fact visible in a diff rather than a runtime lookup.
 */
const row = ledger[ledger.length - 1];
const bundlePath = join(VERSIONS, `${row.label}.json`);
if (!existsSync(bundlePath)) {
  console.log(`  ${RED}x${OFF} the ledger names ${row.label} but ${bundlePath} does not exist`);
  process.exit(1);
}

const bundleText = readFileSync(bundlePath, 'utf8');

// Verified HERE as well as on the device. If the pair going into the generated module does not
// already load, the app would fail at startup on a defect the build could have named.
const bundle = loadPublishedVersion(bundleText, row.checksum, sha256, `${row.label}.json`);

const source = `/* eslint-disable */
// prettier-ignore
/**
 * GENERATED by \`node scripts/generate-corpus-bundle.mjs\`. Do not edit.
 *
 * The published corpus version the app is pinned to, as text, and the root digest the LEDGER
 * records for it — two exports from two files, because a bundle checked against a checksum it
 * carries verifies itself (ADR-0046, ADR-0066).
 *
 * Verified current by \`--check\` inside \`gate:content\`, so a corpus publish that forgets to
 * regenerate fails the build rather than leaving the device on a stale version.
 */

/** The pinned label, e.g. \`2026.08.1\`. */
export const CORPUS_LABEL = ${JSON.stringify(row.label)};

/** The engine semver that produced the derived values in this bundle. */
export const CORPUS_ENGINE = ${JSON.stringify(bundle.engine)};

/** Entries in the bundle. Here so a load can be checked against what was published. */
export const CORPUS_ENTRY_COUNT = ${String(bundle.entries.length)};

/** Palettes in the bundle. */
export const CORPUS_PALETTE_COUNT = ${String(bundle.palettes.length)};

/** The expected root digest, from \`content/versions/index.json\` — never from the bundle. */
export const CORPUS_ROOT_DIGEST = ${JSON.stringify(row.checksum)};

/** The bundle, verbatim. */
export const CORPUS_BUNDLE_TEXT = ${JSON.stringify(bundleText)};
`;

console.log(
  `${DIM}  ${row.label} · ${String(bundle.entries.length)} entries, ` +
    `${String(bundle.palettes.length)} palettes · engine ${bundle.engine}${OFF}`,
);
console.log(`${DIM}  root digest ${row.checksum}${OFF}\n`);

if (CHECK) {
  if (!existsSync(OUT)) {
    console.log(
      `  ${RED}x${OFF} ${OUT} does not exist but would be produced. Run ` +
        '`node scripts/generate-corpus-bundle.mjs`.',
    );
    process.exit(1);
  }
  if (readFileSync(OUT, 'utf8') !== source) {
    console.log(
      `  ${RED}x${OFF} the generated module differs from what ${row.label} produces. Either a ` +
        'corpus version was published without regenerating — in which case the app is pinned ' +
        'to a stale corpus — or the file was hand-edited.',
    );
    process.exit(1);
  }
  console.log(`${GREEN}${BOLD}The app's corpus module is current.${OFF}`);
  process.exit(0);
}

mkdirSync(OUT_DIR, { recursive: true });
writeFileSync(OUT, source, 'utf8');

console.log(
  `  ${GREEN}+${OFF} apps/mobile/src/corpus/generated/bundle.ts  ` +
    `${DIM}${String(source.length)} bytes${OFF}\n`,
);
console.log(`${GREEN}${BOLD}Pinned to ${row.label}.${OFF}`);
